body.query:
query {
  r0: repository(owner:"BiGCAT-UM", name:"BridgeDbR") { ...repoBits }
  r1: repository(owner:"wikipathways", name:"rWikiPathways") { ...repoBits }
  r2: repository(owner:"wikipathways", name:"pywikipathways") { ...repoBits }
  r3: repository(owner:"wikipathways", name:"wikipathways-database") { ...repoBits }
  r4: repository(owner:"PathVisio", name:"pathvisio") { ...repoBits }
  r5: repository(owner:"arrayanalysis", name:"ArrayAnalysis_Shiny") { ...repoBits }
  r6: repository(owner:"vhp4safety", name:"aop-builder") { ...repoBits }
  r7: repository(owner:"vhp4safety", name:"aop-app") { ...repoBits }
  r8: repository(owner:"vhp4safety", name:"O-QT-OECD-QSAR-Toolbox-AI-assistant") { ...repoBits }
  r9: repository(owner:"vhp4safety", name:"MCT8-docking") { ...repoBits }
}

fragment repoBits on Repository {
  nameWithOwner pushedAt isArchived stargazerCount
  primaryLanguage { name }
  licenseInfo { spdxId }
  releases(first:100, orderBy:{field:CREATED_AT, direction:DESC}) {
    nodes { tagName publishedAt isDraft }
  }
  refs(refPrefix:"refs/tags/", first:100,
       orderBy:{field:TAG_COMMIT_DATE, direction:DESC}) {
    nodes { name target { ... on Commit { committedDate }
                          ... on Tag { target { ... on Commit { committedDate } } } } }
  }
}
